import request from "supertest";
import express from "express";
import { setupApp } from "../../../src/setup-app";
import { generateAdminAuthToken } from "../../utils/generate-admin-auth-token";
import { clearDb } from "../../utils/clear-db";
import { POSTS_PATH } from "../../../src/core/paths/paths";
import { HttpStatus } from "../../../src/core/types/types";
import { runDb } from "../../../src/db/mongo.db";
import { SETTINGS } from "../../../src/core/settings/settings";

const thousandChar =
  "";
const thousandNumberChars =
  "";

describe("Posts API validation tests", () => {
  const app = express();
  setupApp(app);

  const adminToken = generateAdminAuthToken();

  beforeAll(async () => {
    await runDb(SETTINGS.MONGO_URL);
    await clearDb(app);
  });

  it("❌ should not create new post; POST /:posts", async () => {
    await request(app)
      .post(POSTS_PATH)
      .send({})
      .expect(HttpStatus.Unauthorized);

    const invalidDataSet1 = await request(app)
      .post(POSTS_PATH)
      .set("Authorization", adminToken)
      .send({
        title: 322, //not a "string"
        shortDescription: 322, //not a "string"
        content: 322, //not a "string"
        blogId: 322, //not a "string"
      })
      .expect(HttpStatus.BadRequest);

    expect(invalidDataSet1.body.errorsMessages).toHaveLength(4);

    const invalidDataSet2 = await request(app)
      .post(POSTS_PATH)
      .set("Authorization", adminToken)
      .send({
        title: "zxcvbnmxzxczxcvbnmazxcvbnmazxcvbnma", //more than 30 char
        shortDescription:
          "8vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ78vFqZ#2xL!Np9r@mKt5sB&JxQ7", //more than 100 char
        content: thousandChar, //more than 1000 char
        blogId: "string", //not a Numeric "string"
      })
      .expect(HttpStatus.BadRequest);

    expect(invalidDataSet2.body.errorsMessages).toHaveLength(4);

    const invalidDataSet3 = await request(app)
      .post(POSTS_PATH)
      .set("Authorization", adminToken)
      .send({
        title: 111111111111111111111111111111111111,
        shortDescription: 1111111111111111111111111111111111111111111111111111111111111111111111111111111111111111111111111111111111111111,
        content: thousandNumberChars,
        blogId: "string",
      })
      .expect(HttpStatus.BadRequest);

    expect(invalidDataSet3.body.errorsMessages).toHaveLength(4);
  });

  it("❌ Should not return post by incorrect id; GET /POSTS/:id", async () => {
    await request(app)
        .get(`${POSTS_PATH}/507f1f77bcf86cd799439011`) 
        .expect(HttpStatus.NotFound);
  });

});
